"desc": "Portretfoto (borstbeeld) van een oudere man, geplaatst bij Remmelt Eisses ten Berge (* Steggerda 4-11-1834, † Overburen 21-9-1909), gehuwd met Maria Jans (Marijke) Oosterkamp, in de publicatie 'Stamboom Lobé en verwanten.' van Gé Lobé. Geboortedatum, -plaats, sterfplaats en partner kloppen met onze kw 42. LET OP: het bijschrift luidt 'Eize Remmelts ten Berge', de naam van zijn vader (kw 84, 1804-1880); de foto kan dus ook de vader zijn. Sterfdatum in de publicatie 21-9-1909, bij ons 21-01-1909 (akte). Dezelfde foto als _2 (andere scan).",
"maker": "onbekend (fotograaf niet vermeld; geplaatst door Gé Lobé, auteur van 'Stamboom Lobé en verwanten.')",
"datum": "onbekend (geschat ca. 1890-1909 naar leeftijd en kleding; niet vermeld)",
