"w": 1095,
"h": 1495,
"t": "Leeuwarder Courant, 4 december 1866: 'Friesland is thans van de runderpest geheel vrij'; onder Hemelum en Harich werden 102 runderen afgemaakt en begraven.",
"desc": "Leeuwarder courant, 1866-12-04, pagina 1, bericht 'LEEUWARDEN, 3 December'. 'Friesland is thans van de runderpest geheel vrij. Men mag zulks toeschrijven aan de spoedige en krachtige maatregelen welke genomen zijn, toen zich onder Hemelum en Harich, gelegen in de aan elkaar grenzende gemeenten Hemelumer Oldephaert en Noordwolde en Gaasterland, ziektegevallen voordeden. Niet alleen de aangetaste runderen, maar ook al de anderen, die daarmede in aanraking konden zijn geweest, te zamen 102 stuks, zijn onteigend, afgemaakt en begraven. ... Voorts is de stal onder Harich, waarop de 2 aangetaste en de 11 verdachte runderen hadden gestaan, naar eisch gedesinfecteerd ... het kwaad, dat zich tot dusverre slechts bepaalde tot 4 hoeven, gelegen in een klein gedeelte van den zuidwestelijken hoek der provincie, voor goed zal zijn gestuit.'",
"maker": "Leeuwarder Courant",
"datum": "1866-12-04",
"lic": "Geen rechtenvermelding bij het krantenbeeld op Delpher (KB; toegang 'accessible'). Krant van vóór 1900; geen auteursrecht.",
