"t": "Het stemkohier van Arum met 1640, 1698 en 1728 naast elkaar. Stem 35: in 1698 'het weeskind van Bocke en Sas Seerps voor de andere ⅔ parten, de beyde laatste papist'; in 1728 'Bocke Bockes ⅓ en Sybrig Lieukama ⅓, de beyde laatste papist'.",
"desc": "Uitsnede (volle breedte, bovenste deel) van scan NL-0400410000_5_3624_000015 (folio 13). Kolommen: plaatsen | Eygenaren 1640 | Eygenaren 1698 || Arum: Eygenaren 1728 | Meyers 1728. Gelezen: 'No. 34 [1640] Gooltje(?) Pytters Scheltinga [1698] De kinderen van Scheltinga, papist [1728] De kinderen van Scheltinga, papist [meier] Ype Rienx(?)'. 'No. 35 [1640] Bocke Seerps Scheltinga [1698] Focke Tjepkes Reitsma voor 1/3 part, het weeskind van Bocke en Sas Seerps voor de andere 2/3 parten, de beyde laatste papist [1728] Focke Tjepkes Reitsma voor 1/3 part, Bocke Bockes 1/3 en Sybrig Lieukama 1/3, de beyde laatste papist [meier 1728] Bocke Bockes'. Stem 2 (scan 000004, folio 2) heeft dezelfde drie eigenaren in 1728 ('Focke Tjepkes Reitsma tot Hemelum voor 1/3 part, Bocke Bockes 1/3 part, Sybrig Luukama 1/3 part, de beide laaste papisten. Synde voorngedagte vyff pondem. Lands niet te vinden'; meier Bocke Bockes) en in 1698 'Bocke kint en Lou(?) Seerps kint te samen voor 2/3 parten ... papist'.",
