"h": 3540,
"t": "Notariële akte van 26 april 1825: 'De eerzame Lucas Siemens Klijnstra, veenbaas, wonende te St. Johannesga' erkent een schuld van 2330 gulden, met hypotheek.",
"desc": "Rechterbladzijde van scan NL-0400410000_26_057014_00132. 'Den 26 April 1825, No. 44. Grosse afgegeven den 13 Mei 1825. Op heden den zes en twintigsten dag der maand April des jaars een duizend agthonderd vijf en twintig compareerde voor ons Sieds Pieters van Goinga, openbaar notaris ... te Heerenveen ... De eerzame Lucas Siemens Klijnstra, veenbaas, wonende te St. Johannesga in de Grieteny Schoterland ... te kennen gevende, dat hij, kragtens eene onderhandsche obligatie van dato den agtsten Maart agttienhonderd en twee ... opregt en deugdelijk verschuldigd ware aan nu wijlen Trijntje Halbes ... als reste van meerdere som twee duizend driehonderd en dertig guldens ...'. Op scan 00133 volgen de onderpanden (klijnland in Tjalleberd, weiland in Sintjohannesga, twee huizen in Sintjohannesga) en zijn handtekening 'L. S. Klijnstra'.",
