"desc": "Uitsnede (onderste deel linkerbladzijde) van scan NL-0400410000_26_078066_000255. Gelezen: '... Waarna, hierby is gevoegd het eerste perceel, staande op drie duizend vierhonderd veertig gulden, 3440. Totaal zeven duizend eenhonderd drie en zeventig gulden vijftig cent, 7173.50, en zijn de drie perceelen alsnu verhoogd geworden door Gerrit Remkes Kingma bovengenoemd een gulden, 1. Gebleven op zeven duizend een honderd vier en zeventig gulden vijftig cent, 7174.50. Geene meerdere verhooging geschied zynde ...'. Begin van de akte (scan 000253): 'No. 76. Heden den zevenden April des jaars 1855 is verschenen voor my Jan Albarda Horatiuszoon, Notaris te Leeuwarden ... ten huize van Nauta op Dreiroemers(?) onder het behoor van Roordahuizum, Hoite Lubartus Lycklama à Nijeholt, landbouwer woonachtig onder het behoor van Roordahuizum ...' (finale toewijzing van drie percelen greidland). Op scan 000254 heet de koper 'Gerrit Remkes Kingma, kastelein en koopman wonende te Oosterwierum'.",
